head.b:skin:
#navbar-iframe, .header, .sidebar, .footer-outer,
.blog-feeds, .post-feeds, .quickedit, .widget-item-control,
.status-msg-wrap, .blog-pager, .post-footer, .comments,
.fauxborder-left, .fauxborder-right, .content-cap-top, .content-cap-bottom,
.feed-links, .titlewrapper, .descriptionwrapper {
  display: none !important;
  border: none !important;
  background: none !important;
  margin: 0 !important;
  padding: 0 !important;
  width: 0 !important;
  height: 0 !important;
}

*, *::before, *::after {
  outline: none;
}

html, body {
  margin: 0 !important;
  padding: 0 !important;
  width: 100% !important;
  max-width: 100% !important;
  background-color: #FCF9F8 !important;
  background-image: none !important;
  overflow-x: hidden !important;
  font-family: 'Inter', system-ui, -apple-system, sans-serif;
}

.main-outer, .content-inner, .columns,
.main, #main, .post, .post-body, .entry-content, .post-outer {
  display: block !important;
  margin: 0 !important;
  padding: 0 !important;
  width: 100% !important;
  max-width: 100% !important;
  background: transparent !important;
  border: none !important;
}

#pageContentWrapper {
  display: none;
  width: 100%;
  min-height: 80vh;
}

body.script:
//
  document.addEventListener('DOMContentLoaded', () => {
    const path = (window.location.pathname || '').toLowerCase();
    const isStaticPage = path.includes('/p/') || path.includes('/b/') || (path.length > 1 && path.endsWith('.html'));
    const isAdminPage = path.includes('admin');

    const homeWrapper = document.getElementById('homeLandingWrapper');
    const pageWrapper = document.getElementById('pageContentWrapper');
    const themeHeader = document.querySelector('header.sticky');
    const themeFooter = document.querySelector('footer');

    if (isAdminPage) {
      if (themeHeader) themeHeader.style.display = 'none';
      if (themeFooter) themeFooter.style.display = 'none';
    }

    // Routing: Tampilkan landing page di root (/), konten Blogger di /p/*.html
    if (homeWrapper && pageWrapper) {
      if (isStaticPage) {
        homeWrapper.style.display = 'none';
        pageWrapper.style.display = 'block';

        // Periksa apakah Blogger sudah menampilkan konten halaman
        const entryBody = pageWrapper.querySelector('.post-body, .entry-content');
        const hasContent = entryBody && entryBody.textContent.trim().length > 15;

        // Fallback load via Blogger Feed API jika widget Blogger kosong
        if (!hasContent) {
          const pageSlug = path.replace('/p/', '').replace('.html', '').replace(/^\/+|\/+$/g, '').toLowerCase();
          fetch('/feeds/pages/default?alt=json')
            .then(res => res.json())
            .then(data => {
              if (data && data.feed && data.feed.entry) {
                const entry = data.feed.entry.find(e => {
                  const altLink = (e.link || []).find(l => l.rel === 'alternate');
                  const linkHref = (altLink ? altLink.href : '').toLowerCase();
                  const entrySlug = linkHref.includes('/p/') ? linkHref.split('/p/')[1].replace('.html', '') : '';
                  const titleText = (e.title && e.title.$t ? e.title.$t : '').toLowerCase().trim();
                  return entrySlug === pageSlug || titleText === pageSlug || linkHref.endsWith('/' + pageSlug + '.html');
                });
                if (entry && entry.content && entry.content.$t) {
                  pageWrapper.innerHTML = '<div class="post-body entry-content">' + entry.content.$t + '</div>';
                  pageWrapper.querySelectorAll('script').forEach(oldScript => {
                    const newScript = document.createElement('script');
                    Array.from(oldScript.attributes).forEach(attr => newScript.setAttribute(attr.name, attr.value));
                    newScript.appendChild(document.createTextNode(oldScript.innerHTML));
                    oldScript.parentNode.replaceChild(newScript, oldScript);
                  });
                  if (typeof lucide !== 'undefined') lucide.createIcons();
                }
              }
            })
            .catch(err => console.error('Gagal memuat konten halaman:', err));
        }
      } else {
        homeWrapper.style.display = 'block';
        pageWrapper.style.display = 'none';
      }
    }

    // Highlight Active Menu
    document.querySelectorAll('#navMenu a').forEach(a => {
      const href = a.getAttribute('href').toLowerCase();
      if ((!isStaticPage && href === '/') || (isStaticPage && href !== '/' && path.includes(href.replace('/p/', '').replace('.html', '')))) {
        a.classList.add('bg-primary-container', 'text-on-primary', 'font-semibold');
        a.classList.remove('text-on-surface-variant');
      } else {
        a.classList.remove('bg-primary-container', 'text-on-primary', 'font-semibold');
        a.classList.add('text-on-surface-variant');
      }
    });

    // Filter & Search Functionality for Seed Catalog
    const filterButtons = document.querySelectorAll('.filter-pill');
    const cards = document.querySelectorAll('.seed-card');
    const searchInput = document.getElementById('bibitSearchInput');
    const clearSearchBtn = document.getElementById('clearSearchBtn');

    let currentFilter = 'all';
    let currentSearch = '';

    function applyFilters() {
      cards.forEach(card => {
        const category = card.getAttribute('data-category');
        const title = (card.getAttribute('data-title') || '').toLowerCase();

        const matchesCategory = (currentFilter === 'all' || category === currentFilter);
        const matchesSearch = title.includes(currentSearch);

        if (matchesCategory && matchesSearch) {
          card.classList.remove('hidden');
        } else {
          card.classList.add('hidden');
        }
      });
    }

    filterButtons.forEach(btn => {
      btn.addEventListener('click', () => {
        filterButtons.forEach(b => {
          b.classList.remove('bg-primary-container', 'text-on-primary');
          b.classList.add('bg-surface-container-lowest', 'text-on-surface-variant');
        });
        btn.classList.remove('bg-surface-container-lowest', 'text-on-surface-variant');
        btn.classList.add('bg-primary-container', 'text-on-primary');

        currentFilter = btn.getAttribute('data-category');
        applyFilters();
      });
    });

    if (searchInput) {
      searchInput.addEventListener('input', (e) => {
        currentSearch = e.target.value.toLowerCase().trim();
        if (clearSearchBtn) {
          if (currentSearch.length > 0) {
            clearSearchBtn.classList.remove('hidden');
          } else {
            clearSearchBtn.classList.add('hidden');
          }
        }
        applyFilters();
      });
    }

    if (clearSearchBtn) {
      clearSearchBtn.addEventListener('click', () => {
        if (searchInput) {
          searchInput.value = '';
          currentSearch = '';
          clearSearchBtn.classList.add('hidden');
          applyFilters();
        }
      });
    }

    // Consultation Form Toast Handler
    const consultForm = document.getElementById('consultationForm');
    if (consultForm) {
      consultForm.addEventListener('submit', (e) => {
        e.preventDefault();
        alert('Terima kasih! Pesan konsultasi Anda telah diterima oleh tim agronomis Go-Tani. Kami akan segera menghubungi nomor WhatsApp Anda.');
        consultForm.reset();
      });
    }

    if (typeof lucide !== 'undefined') lucide.createIcons();
  });
//
